// Z-Lang Transpiler - Register Allocation
// Linear Scan RA, Liveness Analysis, Spilling

fn new_register_allocator() -> any {
  return {
    registers: [],
    allocations: [],
    spills: [],
    intervals: [],
    active: []
  }
}

fn new_live_interval(var_name: string, start: i32, end: i32) -> any {
  return {
    var: var_name,
    start: start,
    end: end,
    register: -1,
    spilled: false
  }
}

fn linear_scan_alloc(intervals: any, num_registers: i32) -> any {
  let active = []
  let allocations = []

  sort_intervals_by_start(intervals)

  let i = 0
  while i < length(intervals) {
    let interval = intervals[i]

    expire_old_intervals(active, interval.start)

    if length(active) < num_registers {
      interval.register = length(active)
      push(active, interval)
    } else {
      let spill = find_spill_candidate(active, interval)

      if spill != -1 {
        let spilled = active[spill]
        spilled.spilled = true
        active[spill] = interval
        interval.register = spilled.register
      } else {
        interval.spilled = true
      }
    }

    push(allocations, interval)
    i = i + 1
  }

  return allocations
}

fn sort_intervals_by_start(intervals: any) -> any {
  // Simple bubble sort for intervals
  let i = 0
  while i < length(intervals) {
    let j = 0
    while j < length(intervals) - 1 {
      if intervals[j].start > intervals[j + 1].start {
        let temp = intervals[j]
        intervals[j] = intervals[j + 1]
        intervals[j + 1] = temp
      }
      j = j + 1
    }
    i = i + 1
  }

  return intervals
}

fn expire_old_intervals(active: any, start: i32) -> any {
  let i = 0
  while i < length(active) {
    let interval = active[i]

    if interval.end < start {
      let new_active = []

      let j = 0
      while j < length(active) {
        if j != i {
          push(new_active, active[j])
        }
        j = j + 1
      }

      active = new_active
    } else {
      i = i + 1
    }
  }

  return active
}

fn find_spill_candidate(active: any, new_interval: any) -> i32 {
  let max_end = -1
  let candidate = -1

  let i = 0
  while i < length(active) {
    let interval = active[i]

    if interval.end > max_end {
      max_end = interval.end
      candidate = i
    }

    i = i + 1
  }

  if candidate != -1 && active[candidate].end > new_interval.end {
    return candidate
  }

  return -1
}

// Coalescing: merge compatible moves
fn coalesce_moves(instructions: any, intervals: any) -> any {
  let i = 0
  while i < length(instructions) {
    let instr = instructions[i]

    if instr.type == "move" {
      let src_interval = find_interval(intervals, instr.src)
      let dst_interval = find_interval(intervals, instr.dst)

      if src_interval != null && dst_interval != null {
        if can_coalesce(src_interval, dst_interval) {
          src_interval.register = dst_interval.register
          instructions[i].type = "noop"
        }
      }
    }

    i = i + 1
  }

  return instructions
}

fn find_interval(intervals: any, var_name: string) -> any {
  let i = 0
  while i < length(intervals) {
    if intervals[i].var == var_name {
      return intervals[i]
    }
    i = i + 1
  }

  return null
}

fn can_coalesce(interval1: any, interval2: any) -> bool {
  if interval1.register == -1 || interval2.register == -1 {
    return false
  }

  if interval1.register == interval2.register {
    return true
  }

  return intervals_dont_overlap(interval1, interval2)
}

fn intervals_dont_overlap(i1: any, i2: any) -> bool {
  return i1.end < i2.start || i2.end < i1.start
}

// Handle spilling: insert spill/reload
fn insert_spills(instructions: any, allocations: any) -> any {
  let i = 0
  while i < length(instructions) {
    let instr = instructions[i]

    if uses_register(instr) {
      let reg = get_register(instr)

      if should_spill(allocations, reg) {
        instructions = insert_reload_before(instructions, i, reg)
        i = i + 1
      }
    }

    if defines_register(instr) {
      let reg = get_register(instr)

      if should_spill(allocations, reg) {
        instructions = insert_spill_after(instructions, i, reg)
        i = i + 1
      }
    }

    i = i + 1
  }

  return instructions
}

fn uses_register(instr: any) -> bool {
  return instr.src != null
}

fn defines_register(instr: any) -> bool {
  return instr.dst != null
}

fn get_register(instr: any) -> string {
  if instr.dst != null {
    return instr.dst
  }
  return instr.src
}

fn should_spill(allocations: any, var_name: string) -> bool {
  let i = 0
  while i < length(allocations) {
    if allocations[i].var == var_name && allocations[i].spilled {
      return true
    }
    i = i + 1
  }

  return false
}

fn insert_reload_before(instructions: any, pos: i32, var_name: string) -> any {
  let reload_instr = {
    type: "reload",
    var: var_name,
    register: find_allocated_register(instructions, var_name, pos)
  }

  let new_instrs = []

  let i = 0
  while i < pos {
    push(new_instrs, instructions[i])
    i = i + 1
  }

  push(new_instrs, reload_instr)

  let j = pos
  while j < length(instructions) {
    push(new_instrs, instructions[j])
    j = j + 1
  }

  return new_instrs
}

fn insert_spill_after(instructions: any, pos: i32, var_name: string) -> any {
  let spill_instr = {
    type: "spill",
    var: var_name,
    register: find_allocated_register(instructions, var_name, pos)
  }

  let new_instrs = []

  let i = 0
  while i <= pos {
    push(new_instrs, instructions[i])
    i = i + 1
  }

  push(new_instrs, spill_instr)

  let j = pos + 1
  while j < length(instructions) {
    push(new_instrs, instructions[j])
    j = j + 1
  }

  return new_instrs
}

fn find_allocated_register(instructions: any, var_name: string, pos: i32) -> i32 {
  let i = 0
  while i < pos {
    let instr = instructions[i]

    if (instr.type == "assign" || instr.type == "load") && instr.dst == var_name {
      return instr.register
    }

    i = i + 1
  }

  return -1
}

// Register Allocation statistics
fn new_ra_stats() -> any {
  return {
    total_intervals: 0,
    allocated_registers: 0,
    spilled_variables: 0,
    moves_coalesced: 0,
    register_efficiency: 0.0
  }
}

fn update_ra_stats(stats: any, allocations: any, num_regs: i32) -> any {
  stats.total_intervals = length(allocations)

  let spilled_count = 0
  let i = 0
  while i < length(allocations) {
    if allocations[i].spilled {
      spilled_count = spilled_count + 1
    }
    i = i + 1
  }

  stats.spilled_variables = spilled_count
  stats.allocated_registers = num_regs

  if num_regs > 0 {
    stats.register_efficiency = 100.0 * (num_regs / stats.total_intervals)
  }

  return stats
}

fn get_ra_stats_string(stats: any) -> string {
  let result = "Register Allocation Stats:\n"
  result = result + "  Total intervals: " + string(stats.total_intervals) + "\n"
  result = result + "  Allocated registers: " + string(stats.allocated_registers) + "\n"
  result = result + "  Spilled variables: " + string(stats.spilled_variables) + "\n"
  result = result + "  Register efficiency: " + string(stats.register_efficiency) + "%\n"

  return result
}

// Z-Lang Transpiler - Optimizer Integration
// 모든 최적화 모듈을 통합한 최적화 파이프라인

fn new_optimizer_pipeline() -> any {
  return {
    cfg: null,
    ir: null,
    loop_stats: null,
    fold_stats: null,
    dce_stats: null,
    ra_stats: null,
    optimization_level: 0
  }
}

fn run_optimization_pipeline(ir: any, cfg: any, opt_level: i32) -> any {
  let pipeline = new_optimizer_pipeline()
  pipeline.ir = ir
  pipeline.cfg = cfg
  pipeline.optimization_level = opt_level

  // Phase 1: Constant Folding (모든 레벨)
  if opt_level >= 1 {
    pipeline.ir = apply_constant_folding(pipeline.ir)
    pipeline.fold_stats = new_fold_stats()
    pipeline.fold_stats.constants_folded = count_folded_constants(pipeline.ir)
  }

  // Phase 2: Dead Code Elimination (O1+)
  if opt_level >= 1 {
    let cfg_analyzer = new_cfg_analyzer()
    let reachable = mark_reachable_blocks(pipeline.cfg)
    let dead_blocks = find_dead_blocks(pipeline.cfg, reachable)

    pipeline.cfg = eliminate_dead_blocks(pipeline.cfg, dead_blocks)
    pipeline.ir = eliminate_dead_code_from_ir(pipeline.ir)

    pipeline.dce_stats = new_dce_stats()
    pipeline.dce_stats.dead_blocks_removed = length(dead_blocks)
  }

  // Phase 3: Loop Optimization (O2+)
  if opt_level >= 2 {
    let loops = find_loops(pipeline.cfg)

    let i = 0
    while i < length(loops) {
      let loop_info = loops[i]

      // LICM
      pipeline.cfg = licm_transform(pipeline.cfg, loop_info)

      // IV Elimination
      pipeline.cfg = iv_elimination(pipeline.cfg, loop_info)

      // Loop Unrolling (O3 only)
      if opt_level >= 3 {
        pipeline.cfg = loop_unroll(pipeline.cfg, loop_info, 4)
      }

      i = i + 1
    }

    pipeline.loop_stats = new_loop_stats()
    pipeline.loop_stats.total_loops = length(loops)
  }

  // Phase 4: Register Allocation (O3+)
  if opt_level >= 3 {
    let num_registers = 8
    let intervals = extract_live_intervals(pipeline.ir)
    let allocations = linear_scan_alloc(intervals, num_registers)

    pipeline.ir = insert_spills(pipeline.ir, allocations)

    pipeline.ra_stats = new_ra_stats()
    pipeline.ra_stats = update_ra_stats(pipeline.ra_stats, allocations, num_registers)
  }

  return pipeline
}

fn apply_constant_folding(ir: any) -> any {
  if ir == null {
    return ir
  }

  // IR의 모든 명령어에 상수 폴딩 적용
  let i = 0
  while i < length(ir.instructions) {
    let instr = ir.instructions[i]

    if instr.type == "assign" && instr.value != null {
      instr.value = fold_constants(instr.value)
    }

    ir.instructions[i] = instr
    i = i + 1
  }

  return ir
}

fn eliminate_dead_code_from_ir(ir: any) -> any {
  if ir == null {
    return ir
  }

  let new_instructions = []

  let i = 0
  while i < length(ir.instructions) {
    let instr = ir.instructions[i]

    // return/break/continue 후의 명령어는 제거
    if instr.type == "return" || instr.type == "break" || instr.type == "continue" {
      push(new_instructions, instr)

      // 다음 명령어 이전까지는 스킵
      i = i + 1
      while i < length(ir.instructions) {
        let next_instr = ir.instructions[i]
        if next_instr.type == "label" {
          break
        }
        i = i + 1
      }
    } else {
      push(new_instructions, instr)
      i = i + 1
    }
  }

  ir.instructions = new_instructions
  return ir
}

fn extract_live_intervals(ir: any) -> any {
  let intervals = []

  // IR에서 사용되는 변수들의 생존 구간 추출
  let i = 0
  while i < length(ir.instructions) {
    let instr = ir.instructions[i]

    if instr.dst != null {
      let interval = new_live_interval(instr.dst, i, i + 1)
      push(intervals, interval)
    }

    i = i + 1
  }

  return intervals
}

fn count_folded_constants(ir: any) -> i32 {
  let count = 0

  let i = 0
  while i < length(ir.instructions) {
    let instr = ir.instructions[i]

    if instr.type == "const" && instr.is_constant == true {
      count = count + 1
    }

    i = i + 1
  }

  return count
}

fn get_optimization_pipeline_stats(pipeline: any) -> string {
  let result = "Optimization Pipeline Report:\\n"
  result = result + "Optimization Level: " + string(pipeline.optimization_level) + "\\n\\n"

  if pipeline.fold_stats != null {
    result = result + get_fold_stats_string(pipeline.fold_stats) + "\\n"
  }

  if pipeline.dce_stats != null {
    result = result + get_dce_stats_string(pipeline.dce_stats) + "\\n"
  }

  if pipeline.loop_stats != null {
    result = result + get_loop_stats_string(pipeline.loop_stats) + "\\n"
  }

  if pipeline.ra_stats != null {
    result = result + get_ra_stats_string(pipeline.ra_stats) + "\\n"
  }

  return result
}

